// Two variable definitions
const vol = [35.0, 40.0, 45.0, 50.0, 55.0, 60.0, 65.0, 70.0, 75.0, 80.0, 85.0, 90.0];
const v = OLI.random(0,11,0);
const volhno3 = vol[v];
const vhno3 = volhno3 .toPrecision(3);

const conca = [0.325, 0.375, 0.425, 0.475, 0.525, 0.575, 0.625, 0.675, 0.725, 0.775, 0.825, 0.875, 0.925, 0.975];
const concb = [0.2, 0.25, 0.3, 0.35, 0.4, 0.45, 0.5, 0.55, 0.6, 0.65, 0.7, 0.75, 0.8, 0.85];
const c1 = OLI.random(0,13,0);
const c2 = OLI.random(0,13,0);
const conchno3 = conca[c1] .toPrecision(3);
const conckoh = concb[c2] .toPrecision(3);

const molhno3 = conchno3*volhno3/1000;
const molhno3sf = molhno3 .toPrecision(3);

const eqpt = volhno3*conchno3/conckoh;
const eqptsf = eqpt .toPrecision(4);

// Initial pH
const ph0 = -Math.log10(conchno3);
const ph0sf = ph0 .toPrecision(3);
const ph0low = 0.99*ph0;
const ph0high = 1.01*ph0;

// pH before equivalence point
const volbefore = OLI.random(9,eqpt - 2,2);
const volbeforesf = volbefore .toPrecision(4);
const molkohbefore = conckoh*volbefore/1000;
const molkohbeforesf = molkohbefore .toPrecision(3);
const molhno31 = (molhno3 - molkohbefore);
const molhno31sf = molhno31 .toPrecision(3);
const vtotal1 = (volhno3 + volbefore)/1000;
const vtotal1sf = vtotal1 .toPrecision(4);
const conchno3before =  (molhno31)/vtotal1;
const conchno3beforesf = conchno3before .toPrecision(3);
const pHbefore = -Math.log10(conchno3before);
const pHbeforesf = pHbefore .toPrecision(3);
const pHbeforelow = 0.99*pHbefore;
const pHbeforehigh = 1.01*pHbefore;

// pH at equivalence point
const moleqpt = conckoh*eqpt/1000;
const moleqptsf = moleqpt .toPrecision(3);

//pH after eq exports
const volafter = OLI.random(eqpt+5, 2*eqpt,2);
const volaftersf = volafter .toPrecision(3);
const molkohafter = conckoh*volafter/1000;
const molkohaftersf = molkohafter .toPrecision(3);
const excesskoh = molkohafter - molhno3;
const excesskohsf = excesskoh .toPrecision(3);
const vtotal2 = (volhno3 + volafter)/1000;
const vtotal2sf = vtotal2 .toPrecision(4);
const conckohafter = excesskoh/(vtotal2);
const conckohaftersf = conckohafter .toPrecision(3);

const pohafter = -Math.log10(conckohafter);
const pohaftersf = pohafter .toPrecision(3);
const phafter = 14 + Math.log10(conckohafter);
const phaftersf = phafter .toPrecision(4);
const phafterlow = 0.99*phafter;
const phafterhigh = 1.01*phafter;

// Expose variables to OLI
module.exports = {
  vhno3, conchno3, molhno3sf, conckoh, eqpt, eqptsf, ph0, ph0sf, ph0low, ph0high, volbefore, volbeforesf, molhno31sf, vtotal1sf, 
  conchno3beforesf, molkohbeforesf, pHbefore, pHbeforesf, pHbeforelow, pHbeforehigh, moleqptsf, volafter, volaftersf, vtotal2sf, molkohaftersf, 
  excesskohsf, conckohaftersf, pohaftersf, phaftersf, phafterlow, phafterhigh, volafter
};
